1	/**
2	 * MLflow Tracing Plugin for OpenCode
3	 *
4	 * This plugin listens for session.idle events and creates MLflow traces
5	 * directly using the @mlflow/core TypeScript SDK.
6	 *
7	 * Usage:
8	 *   1. Install: npm install @mlflow/opencode @mlflow/core
9	 *   2. Add to opencode.json: { "plugin": ["@mlflow/opencode"] }
10	 *   3. Set environment variables:
11	 *      export MLFLOW_TRACKING_URI=http://localhost:5000
12	 *      export MLFLOW_EXPERIMENT_ID=123
13	 *   4. Run opencode normally - tracing happens automatically
14	 */
15	
16	import type { Plugin, PluginInput, Hooks } from '@opencode-ai/plugin';
17	import {
18	  init,
19	  startSpan,
20	  flushTraces,
21	  SpanType,
22	  SpanAttributeKey,
23	  TraceMetadataKey,
24	  InMemoryTraceManager,
25	} from '@mlflow/core';
26	
27	// Track the last processed message count per session to avoid duplicate traces.
28	// On each session.idle event, we compare the current message count with the
29	// last processed count to determine if new messages need tracing.
30	const processedMessageCounts = new Map<string, number>();
31	
32	// Silent plugin - no console output to avoid TUI interference
33	const DEBUG = process.env.MLFLOW_OPENCODE_DEBUG === 'true';
34	
35	// Constants
36	const NANOSECONDS_PER_MS = 1e6;
37	const MAX_PREVIEW_LENGTH = 1000;
38	const MESSAGE_ROLE_USER = 'user';
39	const MESSAGE_ROLE_ASSISTANT = 'assistant';
40	const PART_TYPE_TEXT = 'text';
41	const PART_TYPE_TOOL = 'tool';
42	
43	// SDK initialization state
44	let initialized = false;
45	
46	interface ApiResponse<T> {
47	  data?: T;
48	  error?: unknown;
49	}
50	
51	interface SessionClient {
52	  messages: (params: {
53	    path: { id: string };
54	    query: { limit: number };
55	  }) => Promise<ApiResponse<unknown[]>>;
56	}
57	
58	interface PluginClient {
59	  session: SessionClient;
60	}
61	
62	interface MessagePart {
63	  type: string;
64	  text?: string;
65	  tool?: string;
66	  callID?: string;
67	  state?: {
68	    status?: string;
69	    input?: Record<string, unknown>;
70	    output?: string;
71	    error?: string;
72	    title?: string;
73	    time?: {
74	      start?: number;
75	      end?: number;
76	    };
77	  };
78	}
79	
80	interface MessageInfo {
81	  role?: string;
82	  modelID?: string;
83	  providerID?: string;
84	  tokens?: {
85	    input?: number;
86	    output?: number;
87	    reasoning?: number;
88	    cache?: {
89	      read?: number;
90	      write?: number;
91	    };
92	  };
93	  time?: {
94	    created?: number;
95	    completed?: number;
96	  };
97	}
98	
99	interface Message {
100	  info?: MessageInfo;
101	  parts?: MessagePart[];
102	}
103	
104	/**
105	 * Initialize the MLflow tracing SDK if not already initialized.
106	 * Requires MLFLOW_TRACKING_URI and MLFLOW_EXPERIMENT_ID environment variables.
107	 */
108	function ensureInitialized(): boolean {
109	  if (initialized) {
110	    return true;
111	  }
112	
113	  const trackingUri = process.env.MLFLOW_TRACKING_URI;
114	  const experimentId = process.env.MLFLOW_EXPERIMENT_ID;
115	
116	  if (!trackingUri) {
117	    if (DEBUG) {
118	      console.error('[mlflow] MLFLOW_TRACKING_URI not set, skipping initialization');
119	    }
120	    return false;
121	  }
122	
123	  if (!experimentId) {
124	    if (DEBUG) {
125	      console.error('[mlflow] MLFLOW_EXPERIMENT_ID not set, skipping initialization');
126	    }
127	    return false;
128	  }
129	
130	  try {
131	    init({ trackingUri, experimentId });
132	    initialized = true;
133	    if (DEBUG) {
134	      console.error('[mlflow] SDK initialized successfully');
135	    }
136	    return true;
137	  } catch (error) {
138	    if (DEBUG) {
139	      console.error('[mlflow] Failed to initialize SDK:', error);
140	    }
141	    return false;
142	  }
143	}
144	
145	/**
146	 * Convert timestamp in milliseconds to nanoseconds
147	 */
148	function timestampToNs(timestamp: number | undefined): number | undefined {
149	  return timestamp != null ? Math.floor(timestamp * NANOSECONDS_PER_MS) : undefined;
150	}
151	
152	/**
153	 * Extract the user prompt from messages (find last user message text).
154	 * Concatenates all text parts to handle multi-part user input.
155	 */
156	function extractUserPrompt(messages: Message[]): string {
157	  for (let i = messages.length - 1; i >= 0; i--) {
158	    const msg = messages[i];
159	    if (msg.info?.role === MESSAGE_ROLE_USER) {
160	      const parts = msg.parts || [];
161	      const textParts = parts
162	        .filter((p) => p.type === PART_TYPE_TEXT && p.text)
163	        .map((p) => p.text || '');
164	      if (textParts.length > 0) {
165	        return textParts.join('\n');
166	      }
167	    }
168	  }
169	  return '';
170	}
171	
172	/**
173	 * Extract the assistant response from messages (find last assistant message text).
174	 * Concatenates all text parts to handle multi-part assistant responses.
175	 */
176	function extractAssistantResponse(messages: Message[]): string {
177	  for (let i = messages.length - 1; i >= 0; i--) {
178	    const msg = messages[i];
179	    if (msg.info?.role === MESSAGE_ROLE_ASSISTANT) {
180	      const parts = msg.parts || [];
181	      const textParts = parts
182	        .filter((p) => p.type === PART_TYPE_TEXT && p.text?.trim())
183	        .map((p) => p.text || '');
184	      if (textParts.length > 0) {
185	        return textParts.join('\n');
186	      }
187	    }
188	  }
189	  return '';
190	}
191	
192	/**
193	 * Find the index of the last user message
194	 */
195	function findLastUserMessageIndex(messages: Message[]): number | null {
196	  for (let i = messages.length - 1; i >= 0; i--) {
197	    if (messages[i].info?.role === MESSAGE_ROLE_USER) {
198	      return i;
199	    }
200	  }
201	  return null;
202	}
203	
204	/**
205	 * Reconstruct conversation messages for LLM input history
206	 */
207	function reconstructConversationMessages(
208	  messages: Message[],
209	  endIdx: number,
210	): Array<{ role: string; content: string; tool_call_id?: string }> {
211	  const result: Array<{ role: string; content: string; tool_call_id?: string }> = [];
212	
213	  for (let i = 0; i < endIdx; i++) {
214	    const msg = messages[i];
215	    const role = msg.info?.role;
216	    const parts = msg.parts || [];
217	
218	    if (role === MESSAGE_ROLE_USER) {
219	      const textParts = parts
220	        .filter((p) => p.type === PART_TYPE_TEXT && p.text)
221	        .map((p) => p.text || '');
222	      if (textParts.length > 0) {
223	        result.push({ role: 'user', content: textParts.join('\n') });
224	      }
225	    } else if (role === MESSAGE_ROLE_ASSISTANT) {
226	      const textParts = parts
227	        .filter((p) => p.type === PART_TYPE_TEXT && p.text)
228	        .map((p) => p.text || '');
229	      if (textParts.length > 0) {
230	        result.push({ role: 'assistant', content: textParts.join('\n') });
231	      }
232	
233	      // Add tool results as tool messages
234	      for (const part of parts) {
235	        if (part.type === PART_TYPE_TOOL && part.state?.status === 'completed') {
236	          result.push({
237	            role: 'tool',
238	            tool_call_id: part.callID,
239	            content: part.state.output || '',
240	          });
241	        }
242	      }
243	    }
244	  }
245	
246	  return result;
247	}
248	
249	/**
250	 * Build token usage object for LLM spans
251	 */
252	function buildTokenUsage(tokens: MessageInfo['tokens']): Record<string, number> | null {
253	  if (!tokens) {
254	    return null;
255	  }
256	
257	  const inputTokens = tokens.input || 0;
258	  const outputTokens = tokens.output || 0;
259	  const reasoningTokens = tokens.reasoning || 0;
260	
261	  const usage: Record<string, number> = {
262	    input_tokens: inputTokens,
263	    output_tokens: outputTokens,
264	    total_tokens: inputTokens + outputTokens + reasoningTokens,
265	  };
266	
