 * Utilities for reading and interpreting Codex JSONL rollout (transcript) files.
 */

import * as fs from 'fs';
import type { ContentBlock, RolloutLine } from './types';

const NANOSECONDS_PER_MS = 1e6;

/**
 * Read a JSONL transcript file from disk and parse each non-empty line into a
 * {@link RolloutLine} record.
 */
export function readTranscript(filePath: string): RolloutLine[] {
  const content = fs.readFileSync(filePath, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim().length > 0)
    .map((line) => JSON.parse(line) as RolloutLine);
}

/**
 * Parse an ISO 8601 timestamp string into a nanosecond integer.
 * Returns null for null, undefined, or empty string inputs (or unparseable input).
 */
export function parseTimestampToNs(input: string | null | undefined): number | null {
  if (input === null || input === undefined || input === '') {
    return null;
  }

  const ms = new Date(input).getTime();
  if (Number.isNaN(ms)) {
    return null;
  }

  return Math.floor(ms * NANOSECONDS_PER_MS);
}

/**
 * Extract plain text from a content block array (joining entries with '\n'),
 * return a string argument unchanged, and return '' for undefined.
 */
export function extractTextFromContent(
  content: ContentBlock[] | string | undefined,
): string {
  if (content === undefined) {
    return '';
  }

  if (typeof content === 'string') {
    return content;
  }

  if (Array.isArray(content)) {
    return content
      .filter((block) => block != null && typeof block.text === 'string')
      .map((block) => block.text)
      .join('\n');
  }

  return '';
}

/**
 * Coerce a tool output value into a plain string.
 */
export function extractOutputText(output: unknown): string {
  if (output === undefined || output === null) {
    return '';
  }

  if (typeof output === 'string') {
    return output;
  }

  if (typeof output === 'object') {
    const obj = output as Record<string, unknown>;
    if (typeof obj.content === 'string') {
      return obj.content;
    }
    if (typeof obj.output === 'string') {
      return obj.output;
    }
    return JSON.stringify(output);
  }

  return String(output);
}

/**
 * Return the last user message text found in the transcript, or null if none exists.
 */
export function findLastUserPrompt(records: RolloutLine[]): { text: string } | null {
  for (let i = records.length - 1; i >= 0; i--) {
    const payload = records[i].payload;
    if (payload && payload.role === 'user') {
      return { text: extractTextFromContent(payload.content) };
    }
  }
  return null;
}

/**
 * Return the subset of records belonging to the most recent turn — from the
 * `task_started` event_msg through the `task_complete` event_msg, inclusive.
 */
export function getLastTurnRecords(records: RolloutLine[]): RolloutLine[] {
  let start = -1;
  for (let i = records.length - 1; i >= 0; i--) {
    const record = records[i];
    if (record.type === 'event_msg' && record.payload?.type === 'task_started') {
      start = i;
      break;
    }
  }

  if (start === -1) {
    return [];
  }

  let end = records.length - 1;
  for (let i = start; i < records.length; i++) {
    const record = records[i];
    if (record.type === 'event_msg' && record.payload?.type === 'task_complete') {
      end = i;
      break;
    }
  }

  return records.slice(start, end + 1);
}

/**
 * Find the token_count event in the transcript and return input/output/total tokens.
 * Returns null if no token count event is found.
 */
export function getTokenUsage(
  records: RolloutLine[],
): { input_tokens: number; output_tokens: number; total_tokens: number } | null {
  for (let i = records.length - 1; i >= 0; i--) {
    const record = records[i];
    if (record.type === 'event_msg' && record.payload?.type === 'token_count') {
      const info = record.payload.info ?? {};
      const usage = (info.total_token_usage as Record<string, unknown>) ?? info;
      return {
        input_tokens: Number(usage.input_tokens ?? 0),
        output_tokens: Number(usage.output_tokens ?? 0),
        total_tokens: Number(usage.total_tokens ?? 0),
      };
    }
  }
  return null;
}

/**
 * Return the model name from the session_meta record, or 'unknown' when no
 * model is present in the session metadata.
 */
export function getModel(records: RolloutLine[]): string {
  for (const record of records) {
    if (record.type === 'session_meta') {
      const model = record.payload?.model;
      if (typeof model === 'string' && model.length > 0) {
        return model;
      }
      return 'unknown';
    }
  }
  return 'unknown';
}

/**
 * Return the session ID from the session_meta record in the transcript.
 */
export function getSessionId(records: RolloutLine[]): string {
  for (const record of records) {
    if (record.type === 'session_meta') {
      return record.payload?.id ?? '';
    }
  }
  return '';
}

/**
 * Build a map from call_id strings to tool output strings by scanning
 * function_call_output records. Returns an empty object if no tool outputs
 * are present.
 */
export function buildToolResultMap(records: RolloutLine[]): Record<string, string> {
  const result: Record<string, string> = {};
  for (const record of records) {
    if (record.payload?.type === 'function_call_output') {
      const callId = record.payload.call_id;
      if (callId != null) {
        result[callId] = extractOutputText(record.payload.output);
      }
    }
  }
  return result;
}
