 * MLflow tracing for Codex.
 *
 * Converts Codex `agent-turn-complete` notification payloads (and, for the
 * transcript-based path, JSONL rollout turns) into MLflow spans.
 */

import {
  startSpan,
  flushTraces,
  SpanType,
  SpanStatusCode,
  TraceMetadataKey,
  InMemoryTraceManager,
  type LiveSpan,
} from '@mlflow/core';
import type { ChatMessage, NotifyPayload, RolloutLine } from './types';
import { extractOutputText, extractTextFromContent, parseTimestampToNs } from './transcript';

/**
 * Return the nanosecond timestamp of the `task_started` event_msg in the turn,
 * or null if no such event exists.
 */
export function findTaskStartedNs(turn: RolloutLine[]): number | null {
  for (const record of turn) {
    if (record.type === 'event_msg' && record.payload?.type === 'task_started') {
      return parseTimestampToNs(record.timestamp);
    }
  }
  return null;
}

/**
 * Return the nanosecond timestamp of the `task_complete` event_msg in the turn,
 * or null if no such event exists.
 */
export function findTaskCompleteNs(turn: RolloutLine[]): number | null {
  for (const record of turn) {
    if (record.type === 'event_msg' && record.payload?.type === 'task_complete') {
      return parseTimestampToNs(record.timestamp);
    }
  }
  return null;
}

/**
 * Scan exec_command_end event_msg records and return a map from call_id to
 * { failed, exitCode }. A tool is marked failed when its status is 'failed' or
 * its exit_code is non-zero.
 */
export function buildToolStatuses(
  turn: RolloutLine[],
): Record<string, { failed: boolean; exitCode: number }> {
  const statuses: Record<string, { failed: boolean; exitCode: number }> = {};
  for (const record of turn) {
    if (record.type === 'event_msg' && record.payload?.type === 'exec_command_end') {
      const callId = record.payload.call_id;
      if (callId == null) {
        continue;
      }
      const exitCode = Number(record.payload.exit_code ?? 0);
      const failed = record.payload.status === 'failed' || exitCode !== 0;
      statuses[callId] = { failed, exitCode };
    }
  }
  return statuses;
}

/**
 * Parse a JSON arguments string into an object, falling back to an empty object.
 */
function parseArguments(args: string | undefined): Record<string, unknown> {
  if (!args) {
    return {};
  }
  try {
    const parsed = JSON.parse(args) as unknown;
    if (parsed && typeof parsed === 'object') {
      return parsed as Record<string, unknown>;
    }
    return {};
  } catch {
    return {};
  }
}

/**
 * Convert transcript response_item records (up to but not including uptoIndex)
 * into OpenAI chat-format messages. Messages whose extracted text is empty or
 * whitespace-only are skipped.
 */
export function reconstructMessages(items: RolloutLine[], uptoIndex: number): ChatMessage[] {
  const messages: ChatMessage[] = [];
  const limit = Math.min(uptoIndex, items.length);

  for (let i = 0; i < limit; i++) {
    const record = items[i];
    if (record.type !== 'response_item') {
      continue;
    }

    const payload = record.payload;
    const payloadType = payload.type;

    if (payloadType === 'function_call') {
      messages.push({
        role: 'assistant',
        content: null,
        tool_calls: [
          {
            id: payload.call_id ?? '',
            type: 'function',
            function: {
              name: payload.name ?? '',
              arguments: payload.arguments ?? '',
            },
          },
        ],
      });
      continue;
    }

    if (payloadType === 'function_call_output') {
      const content = extractOutputText(payload.output);
      if (content.trim().length === 0) {
        continue;
      }
      messages.push({
        role: 'tool',
        tool_call_id: payload.call_id ?? '',
        content,
      });
      continue;
    }

    const role = payload.role;
    if (role === 'user' || role === 'assistant' || role === 'developer') {
      const text = extractTextFromContent(payload.content);
      if (text.trim().length === 0) {
        continue;
      }
      messages.push({
        role: role === 'developer' ? 'system' : role,
        content: text,
      });
    }
  }

  return messages;
}

/**
 * Create MLflow LLM and TOOL child spans from a transcript turn. All spans are
 * parented to the given parent span.
 */
export function createChildSpans(
  parent: { spanId: string },
  turn: RolloutLine[],
  model: string,
): void {
  const parentSpan = parent as unknown as LiveSpan;
