  for (const record of turn) {
    if (record.type === 'response_item' && record.payload?.type === 'function_call_output') {
      const callId = record.payload.call_id;
      if (callId != null) {
        outputTsByCallId[callId] = parseTimestampToNs(record.timestamp);
        outputTextByCallId[callId] = extractOutputText(record.payload.output);
      }
    }
  }

  let firstLlm = true;
  let lastFunctionCallOutputNs: number | null = null;

  for (let i = 0; i < turn.length; i++) {
    const record = turn[i];
    if (record.type !== 'response_item') {
      continue;
    }

    const payload = record.payload;
    const payloadType = payload.type;

    if (payload.role === 'assistant' && payloadType !== 'function_call') {
      const startTimeNs = firstLlm ? taskStartedNs : lastFunctionCallOutputNs;
      const endTimeNs = parseTimestampToNs(record.timestamp);
