      const content = extractTextFromContent(payload.content);

      const llmSpan = startSpan({
        name: 'llm_call',
        parent: parentSpan,
        spanType: SpanType.LLM,
        startTimeNs: startTimeNs ?? undefined,
        inputs: { model, messages },
      });
      llmSpan.setOutputs({
        choices: [{ message: { role: 'assistant', content } }],
      });
      llmSpan.end({ endTimeNs: endTimeNs ?? undefined });

      firstLlm = false;
      continue;
    }

    if (payloadType === 'function_call') {
      const callId = payload.call_id ?? '';
      const toolName = payload.name ?? 'unknown';
      const startTimeNs = parseTimestampToNs(record.timestamp);
      const endTimeNs = outputTsByCallId[callId] ?? null;

      const toolSpan = startSpan({
        name: `tool_${toolName}`,
        parent: parentSpan,
        spanType: SpanType.TOOL,
        startTimeNs: startTimeNs ?? undefined,
        inputs: parseArguments(payload.arguments),
        attributes: {
          tool_name: toolName,
          tool_id: callId,
        },
      });

      toolSpan.setOutputs({ result: outputTextByCallId[callId] ?? '' });

      const status = toolStatuses[callId];
      if (status && status.failed) {
        toolSpan.setStatus(
          SpanStatusCode.ERROR,
          `Command failed with exit code ${status.exitCode}`,
        );
      }

      toolSpan.end({ endTimeNs: endTimeNs ?? undefined });
      continue;
    }

    if (payloadType === 'function_call_output') {
      lastFunctionCallOutputNs = parseTimestampToNs(record.timestamp);
    }
  }
}

